import { ApiError } from "@paypal/paypal-server-sdk";
import { orders, paypalRest, payments } from "./client";

/**
 * Every Orders and Payments call goes through the PayPal Server SDK (generated by APIMatic): creating, reading and
 * capturing orders, reading captures, and refunding them. The SDK covers neither Payouts nor Transaction Search,
 * Disputes or webhook verification, so those stay on REST.
 *
 * The payments engine speaks PayPal's own JSON (snake_case), the shape its fake for tests also speaks. This adapter
 * keeps that contract: request bodies are mapped to the SDK's property names, and the answer is PayPal's response
 * body as sent, so the engine and its tests stay unchanged.
 */
type Out<T> = { status: number; body: T; debugId: string | null };

const camel = (key: string) => key.replace(/_([a-z0-9])/g, (_, c: string) => c.toUpperCase());

/** PayPal's JSON names to the SDK's property names, at every depth. Values (enums, amounts, ids) are untouched. */
export function toSdkShape(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(toSdkShape);
  if (value && typeof value === "object") {
    return Object.fromEntries(Object.entries(value as Record<string, unknown>).map(([k, v]) => [camel(k), toSdkShape(v)]));
  }
  return value;
}

function parse(body: unknown): unknown {
  if (typeof body !== "string" || !body.trim()) return {};
  try {
    return JSON.parse(body);
  } catch {
    return {};
  }
}

const header = (headers: Record<string, string> | undefined, name: string) => {
  if (!headers) return null;
  const k = Object.keys(headers).find((h) => h.toLowerCase() === name);
  return k ? headers[k] : null;
};

function headerFromInit(init: RequestInit, name: string): string | undefined {
  const h = init.headers;
  if (!h) return undefined;
  if (h instanceof Headers) return h.get(name) ?? undefined;
  if (Array.isArray(h)) return h.find(([k]) => k.toLowerCase() === name.toLowerCase())?.[1];
  const k = Object.keys(h).find((x) => x.toLowerCase() === name.toLowerCase());
  return k ? (h as Record<string, string>)[k] : undefined;
}

/** Which SDK call serves a REST path, or null when the SDK does not cover it. */
export function sdkRoute(path: string, method: string): { op: string; id?: string } | null {
  const m = method.toUpperCase();
  const clean = path.split("?")[0];
  let x: RegExpMatchArray | null;
  if (clean === "/v2/checkout/orders" && m === "POST") return { op: "createOrder" };
  if ((x = clean.match(/^\/v2\/checkout\/orders\/([^/]+)$/)) && m === "GET") return { op: "getOrder", id: decodeURIComponent(x[1]) };
  if ((x = clean.match(/^\/v2\/checkout\/orders\/([^/]+)\/capture$/)) && m === "POST") return { op: "captureOrder", id: decodeURIComponent(x[1]) };
  if ((x = clean.match(/^\/v2\/payments\/captures\/([^/]+)$/)) && m === "GET") return { op: "getCapturedPayment", id: decodeURIComponent(x[1]) };
  if ((x = clean.match(/^\/v2\/payments\/captures\/([^/]+)\/refund$/)) && m === "POST") return { op: "refundCapturedPayment", id: decodeURIComponent(x[1]) };
  if ((x = clean.match(/^\/v2\/payments\/refunds\/([^/]+)$/)) && m === "GET") return { op: "getRefund", id: decodeURIComponent(x[1]) };
  return null;
}

export async function sdkRest<T>(path: string, init: RequestInit & { requestId?: string } = {}): Promise<Out<T>> {
  const route = sdkRoute(path, init.method ?? "GET");
  if (!route) return paypalRest<T>(path, init);
  const requestId = init.requestId;
  const mock = headerFromInit(init, "PayPal-Mock-Response");
  const body = init.body ? parse(String(init.body)) : undefined;
  const prefer = "return=representation";
  try {
    const res = await (async () => {
      switch (route.op) {
        case "createOrder":
          return orders().createOrder({ body: toSdkShape(body) as never, paypalRequestId: requestId, prefer, paypalMockResponse: mock });
        case "getOrder":
          return orders().getOrder({ id: route.id!, paypalMockResponse: mock });
        case "captureOrder":
          return orders().captureOrder({ id: route.id!, paypalRequestId: requestId, prefer, paypalMockResponse: mock });
        case "getCapturedPayment":
          return payments().getCapturedPayment({ captureId: route.id!, paypalMockResponse: mock });
        case "refundCapturedPayment":
          return payments().refundCapturedPayment({ captureId: route.id!, paypalRequestId: requestId, prefer, paypalMockResponse: mock, body: body ? (toSdkShape(body) as never) : undefined });
        default:
          return payments().getRefund({ refundId: route.id!, paypalMockResponse: mock });
      }
    })();
    return { status: res.statusCode, body: parse(res.body) as T, debugId: header(res.headers, "paypal-debug-id") };
  } catch (e) {
    if (e instanceof ApiError) return { status: e.statusCode, body: parse(e.body) as T, debugId: header(e.headers, "paypal-debug-id") };
    throw e;
  }
}
